{
  "additionalProperties": false,
  "properties": {
    "sub_claims": {
      "items": {
        "additionalProperties": false,
        "properties": {
          "claim_type": {
            "enum": [
              "value",
              "change_pct",
              "change_abs",
              "record_high",
              "record_low",
              "first_time_above",
              "other"
