            "enum": [
              "eq",
              "approx",
              "gt",
              "gte",
              "lt",
              "lte"
            ],
            "type": "string"
          },
          "evidence_ids": {
            "items": {
              "type": "string"
            },
            "type": "array"
          },
          "interpretations": {
            "items": {
              "description": "evidence id like E3 — never free text",
              "type": "string"
            },
            "type": "array"
          },
          "model_found_value": {
            "type": [
              "number",
              "null"
            ]
          },
          "note": {
            "type": "string"
          },
          "stated_text": {
            "type": "string"
          },
          "stated_value": {
            "type": [
              "number",
              "null"
            ]
          },
          "text": {
            "type": "string"
          },
          "verdict": {
            "enum": [
              "supported",
              "contradicted",
              "insufficient_evidence"
            ],
            "type": "string"
          }
        },
        "required": [
          "text",
          "stated_text",
          "claim_type",
          "comparator",
          "stated_value",
          "evidence_ids",
          "interpretations",
          "verdict",
          "note",
          "model_found_value"
        ],
        "type": "object"
      },
      "type": "array"
    },
    "summary": {
      "type": "string"
    },
    "verdict": {
      "enum": [
        "supported",
        "contradicted",
        "insufficient_evidence"
      ],
      "type": "string"
    }
  },
  "required": [
    "verdict",
    "summary",
    "sub_claims"
  ],
  "type": "object"
}

tool_schemas.text:
[
  {
    "description": "Look up one SEC EDGAR XBRL fact for a ticker, metric, and calendar quarter, fiscal quarter (FY2025Q4), or fiscal year. Successful results include period (the normalized requested label, or the resolved label for latest), period_basis (calendar or fiscal), duration_days, and period_type (quarter, ytd, annual, or instant). Additive flows may return derived=true with derivation and components; never treat a ytd result as a quarter or recompute a derived result.",
    "name": "lookup_fact",
    "parameters": {
      "additionalProperties": false,
      "properties": {
        "metric": {
          "enum": [
            "revenue",
            "net_income",
            "operating_income",
            "eps_diluted",
            "gross_profit",
            "total_assets",
            "cash",
            "capex",
            "rd_expense",
            "shares_outstanding"
          ],
          "type": "string"
        },
        "period": {
          "pattern": "^(latest|FY\\d{4}(?:Q[1-4])?|\\d{4}Q[1-4])$",
          "type": "string"
        },
        "ticker": {
          "type": "string"
        }
      },
      "required": [
        "ticker",
        "metric",
        "period"
      ],
      "type": "object"
    },
    "strict": true,
    "type": "function"
  },
  {
    "description": "List the recent directly available SEC EDGAR quarter and fiscal-year periods for a ticker and metric.",
    "name": "list_periods",
    "parameters": {
      "additionalProperties": false,
      "properties": {
        "metric": {
          "enum": [
            "revenue",
            "net_income",
            "operating_income",
            "eps_diluted",
            "gross_profit",
            "total_assets",
            "cash",
            "capex",
            "rd_expense",
            "shares_outstanding"
          ],
          "type": "string"
        },
        "ticker": {
          "type": "string"
        }
      },
      "required": [
        "ticker",
        "metric"
      ],
      "type": "object"
    },
    "strict": true,
    "type": "function"
  },
  {
    "description": "Compute the absolute and year-over-year change for one SEC EDGAR XBRL metric. The period and base_period must be the same kind of period; when base_period is omitted, null, empty, \"null\", or \"none\", use the same quarter or fiscal year one year earlier. The result includes both cited lookup facts and a percentage change in percent points.",
    "name": "compute_change",
    "parameters": {
      "additionalProperties": false,
      "properties": {
        "base_period": {
          "pattern": "^(FY\\d{4}(?:Q[1-4])?|\\d{4}Q[1-4])$",
          "type": [
            "string",
            "null"
          ]
        },
        "metric": {
          "enum": [
            "revenue",
            "net_income",
            "operating_income",
            "eps_diluted",
            "gross_profit",
            "total_assets",
            "cash",
            "capex",
            "rd_expense",
            "shares_outstanding"
          ],
          "type": "string"
        },
        "period": {
          "pattern": "^(latest|FY\\d{4}(?:Q[1-4])?|\\d{4}Q[1-4])$",
          "type": "string"
        },
        "ticker": {
          "type": "string"
        }
      },
      "required": [
        "ticker",
        "metric",
        "period",
        "base_period"
      ],
      "type": "object"
    },
    "strict": true,
    "type": "function"
  },
  {
    "description": "Compare one quarter or fiscal-year fact with every available comparable period of the same period_type. Quarters include derived Q4 values when available; annual periods are compared only with annual periods. Return the rank, record flags through the requested period, prior high/low, and the comparison window with period end dates.",
    "name": "history_rank",
    "parameters": {
      "additionalProperties": false,
      "properties": {
        "metric": {
          "enum": [
            "revenue",
            "net_income",
            "operating_income",
            "eps_diluted",
            "gross_profit",
            "total_assets",
            "cash",
            "capex",
            "rd_expense",
            "shares_outstanding"
          ],
          "type": "string"
        },
        "period": {
          "pattern": "^(latest|FY\\d{4}(?:Q[1-4])?|\\d{4}Q[1-4])$",
          "type": "string"
        },
        "ticker": {
          "type": "string"
        }
      },
      "required": [
        "ticker",
        "metric",
        "period"
      ],
      "type": "object"
    },
    "strict": true,
    "type": "function"
  }
]
